from prepare import *
rows=read(O/'category_check/sample_100.csv')
# Agent visually inspected all original/masked pairs in page_01 through page_10.
issues={7:'Ảnh đại diện: áo ren nổi bật; phần quần bị cắt, chưa xác nhận category sản phẩm quần từ ảnh này.',11:'Có vest và quần rõ trong ảnh gốc nhưng mask đen; unknown không phản ánh trang phục.',27:'Ảnh gốc rõ áo sơ mi, mask đen; unknown sai ngữ nghĩa.',28:'Ảnh toàn thân: quần chiếm vùng lớn; nhãn áo thân trên chưa phù hợp hình đại diện.',33:'Ảnh toàn thân quần có vùng lớn hơn áo; chưa xác nhận nhãn áo thân trên.',40:'Quan sát là váy liền sọc, không phải chân váy.',49:'Khung hình cho thấy áo và quần cắt ngang; không đủ bằng chứng xác nhận đa số sản phẩm là quần.',58:'Quần dài chiếm vùng lớn của ảnh đại diện; nhãn áo thân trên chưa chắc đúng.',65:'Trang phục xanh có vẻ quần liền/playsuit, chưa xác nhận chân váy; tính sai bảo thủ.',75:'Trang phục hoa có vẻ bộ liền/playsuit, chưa xác nhận chân váy; tính sai bảo thủ.',96:'Áo dài phối quần đen, không xác nhận là váy liền.',100:'Trang phục hoa có thân áo nối phần dưới, có vẻ váy liền; không xác nhận chân váy.'}
for i,r in enumerate(rows,1):
 r.update(correct=int(i not in issues),note=issues.get(i,'Ảnh gốc và mask hỗ trợ loại trang phục gán; kiểm tra thị giác agent, chưa phải nhãn chuẩn con người.'),montage=f'page_{(i-1)//10+1:02d}.png',cell=(i-1)%10+1)
write(O/'category_check_100.csv',rows)
dump(O/'category_check_result.json',{'correct':sum(r['correct'] for r in rows),'total':100,'passed':sum(r['correct'] for r in rows)>=90,'reviewer':'agent','human_review_required':True,'uncertain_counted_incorrect':True,'note':'Đánh giá ngữ nghĩa ảnh đại diện so với category sản phẩm; không suy nhãn thật từ diện tích mask. Không phải đo accuracy của mã majority trên toàn bộ ảnh. Mẫu trải đều strata, không phải ngẫu nhiên đơn toàn tập.'})
